package com.fooddelivery.payment.controller;import org.springframework.web.bind.annotation.*;import com.fooddelivery.payment.dto.PaymentRequest;import com.fooddelivery.payment.entity.Payment;import com.fooddelivery.payment.service.PaymentService;@RestController @RequestMapping("/api/payments")public class PaymentController{private final PaymentService s;public PaymentController(PaymentService s){this.s=s;}@PostMapping public Payment pay(@RequestBody PaymentRequest q){return s.pay(q);}}
